  const workspaces=useSyncExternalStore(fn=>ctx.workspaces.list.subscribe(fn),()=>ctx.workspaces.list.getSnapshot());
  const sessions=useSyncExternalStore(ctx.sessions.list.subscribe,ctx.sessions.list.getSnapshot);
